/// The Senzing API usage groups: which flags each engine method accepts.
public enum SzFlagUsageGroup: String, CaseIterable, Sendable {
    /// `SzAddRecordFlags`.
    case addRecord = "SzAddRecordFlags"
    /// `SzDeleteRecordFlags`.
    case deleteRecord = "SzDeleteRecordFlags"
    /// `SzEntityFlags`.
    case entity = "SzEntityFlags"
    /// `SzExportFlags`.
    case export = "SzExportFlags"
    /// `SzFindInterestingEntitiesFlags`.
    case findInterestingEntities = "SzFindInterestingEntitiesFlags"
    /// `SzFindNetworkFlags`.
    case findNetwork = "SzFindNetworkFlags"
