    /// `SzWhyRecordsFlags`.
    case whyRecords = "SzWhyRecordsFlags"
    /// `SzWhySearchFlags`.
    case whySearch = "SzWhySearchFlags"

    /// Every flag that applies to this usage group (empty when the
    /// group's methods take no flags).
    public var allFlags: SzFlags {
        switch self {
        case .addRecord: SzFlags(rawValue: 0x4000_0000_0000_0000)
        case .deleteRecord: SzFlags(rawValue: 0x4000_0000_0000_0000)
        case .entity: SzFlags(rawValue: 0x0000_029C_B1FD_FFC0)
        case .export: SzFlags(rawValue: 0x0000_029C_B1FD_FFFF)
        case .findInterestingEntities: []
        case .findNetwork: SzFlags(rawValue: 0x0000_029E_B1FD_FFC0)
