        case .record: SzFlags(rawValue: 0x0000_0298_8085_0000)
        case .recordPreview: SzFlags(rawValue: 0x0000_0218_8085_0000)
        case .redo: SzFlags(rawValue: 0x4000_0000_0000_0000)
        case .reevaluateEntity: SzFlags(rawValue: 0x4000_0000_0000_0000)
        case .reevaluateRecord: SzFlags(rawValue: 0x4000_0000_0000_0000)
        case .search: SzFlags(rawValue: 0x0000_02FD_BDFD_FFCF)
